fn reverse(a: &[i32]) -> Vec<i32> {
    let n = a.len();
    let mut result = Vec::with_capacity(n);

    // Push elements from the end of `a` to the start.
    for i in 0..n {
        result.push(a[n - 1 - i]);
    }

    result
}